+        assert!(
+            db.compare_and_set_root_title("root", Some("new"), new_event, "new")
+                .unwrap()
+        );
+        assert!(
+            !db.compare_and_set_root_title(
+                "root",
+                Some("manual during request"),
+                fresh_event,
+                "duplicate"
+            )
+            .unwrap()
+        );
