+    );
+    let owner = app.clone();
+    let target = session.clone();
+    let first = tokio::spawn(async move { owner.regenerate_title(target).await });
+    tokio::time::timeout(Duration::from_secs(3), async {
+        while requests.lock().unwrap().is_empty() {
